// Normaliza campos recibidos del formulario o del disparador manual
const fecha = $now.setZone('America/La_Paz').toFormat('yyyy-MM-dd HH:mm');
const items = $input.all();

return items.map((item) => {
  const r = item.json;
  return {
    json: {
      user_id: 'a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11',
      nombre_artista: String(r.nombre_artista || 'Camila Vargas').trim(),
      titulo_obra: String(r.titulo_obra || 'Avance artístico').trim(),
      categoria: String(r.categoria || 'Retrato a grafito'),
      notas_creadora: String(r.notas_creadora || 'Práctica de volumen y proporciones').trim(),
      imagen_url: r.imagen_url || 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=600&auto=format&fit=crop&q=80',
      fecha_entrega: fecha,
      tiene_binario: Boolean(item.binary && item.binary.foto)
    },
    ...(item.binary ? { binary: item.binary } : {})
  };
});

// Carga el contexto de la obra anterior (Semana 1) de la base de datos o fallback
// para garantizar que la demo funcione con o sin conexión activa a Supabase.
const entregaActual = $input.first().json;

// Obra de referencia histórica (Semana 1)
const obraAnterior = {
  titulo: 'Boceto inicial de rostro (Semana 1)',
  categoria: 'Retrato a grafito',
  notas: 'Primer intento en 3/4. Ojos desiguales y sombreado plano.',
  score_anterior: 62,
  mejoras_sugeridas_previamente: 'Construir eje de simetría y usar grafito más blando (4B) para profundidad',
  reto_previo: 'Dibuja 3 pares de ojos en perspectiva de 3/4 usando una línea guía de horizonte.'
};

const promptComparativo = `
DATOS DE LA CREADORA:
- Artista: ${entregaActual.nombre_artista}
- Disciplina: ${entregaActual.categoria}

HISTORIAL ANTERIOR (Semana 1):
- Título anterior: "${obraAnterior.titulo}"
- Notas anteriores: "${obraAnterior.notas}"
- Puntaje anterior: ${obraAnterior.score_anterior}/100
- Reto que tenía pendiente: "${obraAnterior.reto_previo}"

NUEVA ENTREGA ACTUAL (Semana 2):
- Título actual: "${entregaActual.titulo_obra}"
- Categoría: "${entregaActual.categoria}"
- Notas de la creadora sobre su avance: "${entregaActual.notas_creadora}"

Evalúa la evolución de la artista considerando si cumplió el reto previo y cómo mejoró su técnica.` ;

return [{
  json: {
    ...entregaActual,
    obra_anterior: obraAnterior,
    prompt_comparativo: promptComparativo
  },
  ...($input.first().binary ? { binary: $input.first().binary } : {})
}];

// Extrae los resultados de Gemini y prepara el reporte final
const item = $input.first();
const ia = item.json.output || {};
const previo = $('Recuperar Memoria Evolutiva').first().json;

const score = Number(ia.puntaje_progreso) || 85;
const scoreAnterior = previo.obra_anterior?.score_anterior || 62;
const ganancia = score - scoreAnterior;

return [{
  json: {
    artista: previo.nombre_artista,
    titulo_obra: previo.titulo_obra,
    categoria: previo.categoria,
    score_actual: score,
    score_anterior: scoreAnterior,
    evolucion_neta: (ganancia >= 0 ? `+${ganancia}%` : `${ganancia}%`),
    evaluacion_general: ia.evaluacion_general || 'Has demostrado un progreso notable en la estructura general y la dirección del trazo.',
    logros_destacados: ia.logros_destacados || 'Alineación precisa del eje de ojos en 3/4 y mayor profundidad en el pómulo.',
    mejoras_tecnicas: ia.mejoras_tecnicas || '1. Suavizar la transición entre el sombreado 4B y la luz alta.\n2. Definir con mayor precisión la línea del lagrimal.',
    siguiente_reto_titulo: ia.siguiente_reto_titulo || 'Reto Semana 3: Luces y reflejos en la mirada',
    siguiente_reto_consigna: ia.siguiente_reto_consigna || 'Dibuja el mismo retrato aplicando una goma maleable para reservar los brillos especulares en la pupila.',
    mensaje_aliento: ia.mensaje_aliento || '¡Gran trabajo, Camila! La constancia es el secreto de las grandes maestras.',
    fecha: previo.fecha_entrega
  }
}];

